insert into site_settings (id, studio_name, tagline, city, state, country, address, email, phone, instagram, linkedin, pinterest, whatsapp_number, whatsapp_default_message, google_maps_url, google_maps_embed_url, footer_description, working_hours, meta_title, meta_description) values
('00000000-0000-0000-0000-000000000001', 'Manvvi Design Studio', 'Interior Architecture & Design Studio', 'Mumbai', 'Maharashtra', 'India', 'Office no 48, Second floor, Gopal Mansion A, Turner Rd, Bandra West, Mumbai, Maharashtra 400050', 'info@manvvidesignstudio.com', '+91 87936 16240', 'https://instagram.com/manvvidesignstudio', 'https://linkedin.com/company/manvvi-design-studio', 'https://pinterest.com', '918793616240', 'Hello Manvvi Design Studio, I would like to inquire about a project.', 'https://maps.google.com/?q=Manvvi+Design+Studio&ll=19.0583987,72.8351577', 'https://www.google.com/maps?q=Gopal+Mansion+A,+Turner+Road,+Bandra+West,+Mumbai&output=embed', 'A full-scale residential and commercial interior design studio in Mumbai. We shape homes and creative environments through thoughtful space transformations, refined layouts, and precise site execution.', 'Monday – Saturday: 10:00 AM – 7:00 PM IST; Sunday: Closed', 'Manvvi Design Studio | Interior Architecture & Design Studio in Mumbai', 'A Mumbai-based interior design studio delivering residential and commercial space transformations, layout conceptualization, and site execution.')
insert into hero_content (id, eyebrow, headline, subheadline, primary_cta_text, primary_cta_link, secondary_cta_text, secondary_cta_link, background_image_url) values
('00000000-0000-0000-0000-000000000002', 'MANVVI DESIGN STUDIO', 'Interiors built around how you actually live.', 'A Mumbai-based design studio shaping homes and workspaces with restraint, craft, and a point of view.', 'View the portfolio ↗', '/portfolio', 'Start a conversation', '/contact', 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?q=85&w=2400&auto=format&fit=crop')
insert into studio_content (id, intro_eyebrow, intro_heading, intro_body, story_heading, story_text, founder_name, founder_title, founder_quote, founder_image_url, stats) values
('00000000-0000-0000-0000-000000000003', 'OUR APPROACH', 'Spaces that feel considered, not decorated.', 'At Manvvi Design Studio, we believe interiors should respond to the people who inhabit them. Our work brings together architecture, material, light and everyday rituals to create spaces that feel timeless and deeply personal.', 'Rooted in Mumbai, Crafted for Quiet Living', 'Founded in Mumbai, Manvvi Design Studio is an interior architecture practice driven by spatial discipline, honest materiality, and quiet luxury. We reject the fleeting noise of seasonal trends in favor of enduring proportion, natural stone, sculpted timber, and daylight that moves gracefully across walls.', 'Manvvi Sharma', 'Founder & Principal Architect', 'Great interior architecture does not seek to shout; it provides a serene, tactile sanctuary where life naturally unfolds.', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?q=80&w=1200&auto=format&fit=crop', '[{"value":"15+","label":"Selected Projects","sub":"Completed across Maharashtra & beyond"},{"value":"8+","label":"Cities","sub":"Mumbai, Goa, Bengaluru & Alibaug"},{"value":"6+","label":"Years of Experience","sub":"Dedicated luxury residential practice"},{"value":"100%","label":"Personalized Design","sub":"Bespoke joinery, stone & spatial curation"}]'::jsonb)
insert into projects (id, title, slug, location, year, category, short_description, description, concept, material_palette, cover_image, gallery_images, before_image, after_image, project_specs, featured, published, display_order) values
('524c0e2a-272e-5743-8a39-3eb0cedaa108', 'The Courtyard Residence', 'the-courtyard-residence', 'Bandra West, Mumbai', '2026', 'Residential', 'A monolithic private villa woven around a central open-sky verdant courtyard, sculpted in travertine and smoked oak.', 'The Courtyard Residence was envisioned as a tranquil sanctuary amidst the bustling energy of Mumbai. The layout is arranged around an internal open-to-sky courtyard lined with rough-hewn basalt stone and lush tropical flora. Natural cross-ventilation, shaded verandas, and continuous travertine flooring create an uninterrupted rhythm between indoor living and outdoor landscape.', 'A contemplative dialogue between raw earth and refined geometry. Every room opens towards the light well, allowing shadows to trace the time of day across tactile lime-plastered walls.', '["Roman Travertine","Smoked European Oak","Brushed Champagne Brass","Hand-applied Lime Plaster","Fluted Cast Glass"]'::jsonb, 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?q=85&w=2000&auto=format&fit=crop', '["https://images.unsplash.com/photo-1600585154340-be6161a56a0c?q=85&w=1800&auto=format&fit=crop","https://images.unsplash.com/photo-1600565193348-f74bd3c7ccdf?q=85&w=1800&auto=format&fit=crop","https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?q=85&w=1800&auto=format&fit=crop","https://images.unsplash.com/photo-1600585154526-990dced4db0d?q=85&w=1800&auto=format&fit=crop"]'::jsonb, 'https://images.unsplash.com/photo-1513694203232-719a280e022f?q=80&w=1400&auto=format&fit=crop', 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?q=85&w=1400&auto=format&fit=crop', '{"area":"5,800 sq.ft","scope":"Full Interior Architecture & Custom Millwork","timeline":"14 Months","client":"Private Family"}'::jsonb, true, true, 1),
('598eaf3a-0f0b-5b96-b10d-ea3c0f04aea3', 'Mumbai Hills Residence', 'mumbai-hills-residence', 'Mumbai Hills', '2025', 'Residential', 'An elevated hillside villa overlooking the Sahyadri range, balancing warm cedar ceilings with monolithic terrazzo.', 'Perched along the ridgelines overlooking Mumbai western hills, this residence captures wide panoramic views while maintaining deep thermal comfort. Large architectural overhangs protect floor-to-ceiling glazing from intense monsoon rains and afternoon sun, framing mist-covered ridges in every living zone.', 'Architecture as an observational frame. Materials were selected to patina gracefully alongside the mountain climate.', '["Natural Cedar Slatting","Grey River Terrazzo","Anodized Bronze","Linen Upholstery"]'::jsonb, 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?q=85&w=2000&auto=format&fit=crop', '["https://images.unsplash.com/photo-1600573472591-ee6b68d14c68?q=85&w=1800&auto=format&fit=crop","https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?q=85&w=1800&auto=format&fit=crop","https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?q=85&w=1800&auto=format&fit=crop"]'::jsonb, null, null, '{"area":"6,400 sq.ft","scope":"Interior Architecture & Landscape Integration","timeline":"18 Months","client":"Industrialist"}'::jsonb, true, true, 2),
('9c0d2fe7-a750-5f5a-bec3-1315198fa264', 'The Ivory Apartment', 'the-ivory-apartment', 'Turner Road, Bandra West', '2026', 'Residential', 'An expansive high-rise penthouse defined by tone-on-tone ivory textures, custom curved joinery, and soft ambient illumination.', 'The Ivory Apartment reinterprets penthouse luxury through extreme textural nuance rather than decorative clutter. A restrained palette of alabaster micro-cement, ivory bouclé, honed Calacatta marble, and bleached walnut creates an atmosphere of weightlessness above the city.', 'Soft minimalism. Curved architectural transitions guide movement fluidly from the gallery foyer to the sunset terrace.', '["Honed Calacatta Marble","Ivory Micro-cement","Bleached Walnut","Silk-Wool Rugs","Matte Architectural Glass"]'::jsonb, 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?q=85&w=2000&auto=format&fit=crop', '["https://images.unsplash.com/photo-1600585152220-90363fe7e115?q=85&w=1800&auto=format&fit=crop","https://images.unsplash.com/photo-1600565193348-f74bd3c7ccdf?q=85&w=1800&auto=format&fit=crop","https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?q=85&w=1800&auto=format&fit=crop"]'::jsonb, null, null, '{"area":"4,100 sq.ft","scope":"Penthouse Renovation & Turnkey Furniture Curation","timeline":"10 Months","client":"Tech Executive"}'::jsonb, true, true, 3),
('89e3fbd3-aa2d-5d2f-a38e-ceba6919b3f8', 'Casa Verde', 'casa-verde', 'Bandra West, Mumbai', '2025', 'Residential', 'A heritage bungalow reimagined with deep forest green marble, restored teakwood rafters, and bespoke brass joinery.', 'Nestled beneath century-old rain trees in Bandra West, Casa Verde merges historical colonial proportions with clean, modern sensibilities. Original high ceilings were restored to expose teak trusses, juxtaposed against deep Indian green marble kitchen islands and minimalist iron-framed apertures.', 'Honoring heritage through contemporary restraint. The deep green tones reflect the lush botanical canopy outside.', '["Udaipur Green Marble","Restored Indian Teak","Blackened Steel","Hand-glazed Ceramic Tiles"]'::jsonb, 'https://images.unsplash.com/photo-1600565193348-f74bd3c7ccdf?q=85&w=2000&auto=format&fit=crop', '["https://images.unsplash.com/photo-1600585154340-be6161a56a0c?q=85&w=1800&auto=format&fit=crop","https://images.unsplash.com/photo-1600573472591-ee6b68d14c68?q=85&w=1800&auto=format&fit=crop"]'::jsonb, null, null, '{"area":"4,800 sq.ft","scope":"Heritage Restoration & Interior Design","timeline":"15 Months","client":"Doctor & Writer Couple"}'::jsonb, false, true, 4),
('861c92f3-e26c-5eba-97c1-f4804b0af25c', 'Urban Retreat Studio', 'urban-retreat-studio', 'Bandra West, Mumbai', '2026', 'Commercial', 'An architectural design atelier and executive workspace fostering stillness, collaboration, and creative focus.', 'Created as a multidisciplinary creative workspace, the design strips away the cold uniformity of corporate offices in favor of residential warmth. Acoustic felt wall paneling, sculpted oak desks, hidden cable channels, and diffused paper lanterns cultivate a calm, library-like atmosphere.', 'The tactile office: a working sanctuary that calms the senses and encourages uninterrupted focus.', '["Acoustic Taupe Wool","Natural White Ash","Raw Cast Aluminium","Washi Paper Lanterns"]'::jsonb, 'https://images.unsplash.com/photo-1497366216548-37526070297c?q=85&w=2000&auto=format&fit=crop', '["https://images.unsplash.com/photo-1497366811353-6870744d04b2?q=85&w=1800&auto=format&fit=crop","https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?q=85&w=1800&auto=format&fit=crop"]'::jsonb, null, null, '{"area":"3,200 sq.ft","scope":"Commercial Interior Architecture & Lighting Design","timeline":"8 Months","client":"Venture Capital & Design Consultancy"}'::jsonb, false, true, 5),
('68d8e386-48b9-5f8a-bd60-40dfe7922a49', 'The Minimal House', 'the-minimal-house', 'Bandra West, Mumbai', '2025', 'Residential', 'A study in pure geometry and subtraction, where bespoke recessed storage allows architecture to breathe freely.', 'A bold exercise in intentional reduction. In this home, all non-essential decorative elements were eliminated. Storage, air conditioning, and electrical conduits are completely concealed behind flush millwork panels, leaving only pure light, shadow, and sculptural volume.', 'Subtraction as ultimate luxury. The absence of clutter creates space for mindfulness.', '["Limestone Flooring","Matte Lacquer Joinery","Brushed Gunmetal","Sheer Belgian Linen"]'::jsonb, 'https://images.unsplash.com/photo-1600585154526-990dced4db0d?q=85&w=2000&auto=format&fit=crop', '["https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?q=85&w=1800&auto=format&fit=crop","https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?q=85&w=1800&auto=format&fit=crop"]'::jsonb, null, null, '{"area":"3,800 sq.ft","scope":"Interior Architecture & Custom Lighting","timeline":"12 Months","client":"Architectural Enthusiast"}'::jsonb, false, true, 6),
('7c56d9e7-80cb-5886-a074-2459f8d4f3b3', 'Bandra Atrium Suite', 'bandra-atrium-suite', 'Bandra West, Mumbai', '2025', 'Hospitality', 'A boutique luxury hospitality suite featuring double-height ceiling volumes and dramatic custom lighting.', 'Designed for a private boutique hotel property, this hospitality suite emphasizes theatrical volume and cocoon-like comfort. Sculptural lighting installations anchor double-height lounge ceilings, paired with deep marble soaker tubs and curated art collections.', 'Atmospheric drama. Intimate zones carved within grand vertical volumes.', '["Nero Marquina Marble","Velvet Drapery","Smoked Bronze Glass","Hand-knotted Silk"]'::jsonb, 'https://images.unsplash.com/photo-1590490360182-c33d57733427?q=85&w=2000&auto=format&fit=crop', '["https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?q=85&w=1800&auto=format&fit=crop"]'::jsonb, null, null, '{"area":"2,600 sq.ft","scope":"Hospitality Design & Bespoke FF&E","timeline":"9 Months","client":"Boutique Hotelier"}'::jsonb, false, true, 7),
('09844bf0-4c25-5d10-97c7-8343684d38ca', 'Aura Wellness Pavilion', 'aura-wellness-pavilion', 'Mulshi Lake, Maharashtra', '2026', 'Commercial', 'An organic lakeside wellness pavilion crafted with rammed earth walls, cedar louvers, and reflection pools.', 'Situated along the serene shores of Mumbai outskirts, this wellness pavilion blurs the boundary between architecture and landscape. Rammed earth construction made with locally sourced red clay provides natural insulation, while perimeter water pools catch flickering reflections of the setting sun.', 'Biophilic immersion. Architecture constructed of the very soil upon which it stands.', '["Rammed Earth","Local Basalt Stone","Reclaimed Cedar","Copper Accents"]'::jsonb, 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?q=85&w=2000&auto=format&fit=crop', '["https://images.unsplash.com/photo-1512917774080-9991f1c4c750?q=85&w=1800&auto=format&fit=crop"]'::jsonb, null, null, '{"area":"7,200 sq.ft","scope":"Holistic Spatial Architecture & Landscape Curation","timeline":"20 Months","client":"Wellness Resort Group"}'::jsonb, false, true, 8)
insert into services (id, title, slug, tagline, description, deliverables, process_summary, image_url, icon, display_order, published) values
('0a74c04e-eb95-5cb2-96bd-68181e0ad0a0', 'Residential Interiors', 'residential-interiors', 'Refined living spaces tailored to personal ritual', 'Complete interior design and architecture for premium private residences. We curate every spatial zone to flow seamlessly, ensuring lighting, acoustics, and tactile surfaces elevate your daily routines.', '["Custom Space Planning","3D Visual Simulations","Lighting & Electrical Design","Complete Material Sourcing","Site Execution Supervision"]'::jsonb, 'From initial spatial audit to turnkey handover, we oversee every square inch with obsessive attention to craftsmanship.', 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?q=80&w=1400&auto=format&fit=crop', 'Home', 1, true),
('feba4459-104f-57e3-aa29-fa618a669806', 'Luxury Residences & Villas', 'luxury-residences', 'Architectural scale residences & private estates', 'Comprehensive design for large-scale custom villas, farmhouses, and sprawling penthouses. We coordinate internal architecture, courtyard transitions, bespoke stone quarry selections, and smart automation.', '["Architectural Layout Optimization","Bespoke Facade & Interior Integration","Quarry-direct Stone Selection","Climate & Shading Strategy","Full Contractor Tender Packages"]'::jsonb, 'We work closely with project architects and structural teams to ensure interiors and built forms speak a single coherent dialect.', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?q=80&w=1400&auto=format&fit=crop', 'Crown', 2, true),
('c747bff6-50e8-5fb5-8bc8-9c0194c9fb55', 'Apartment Interiors', 'apartment-interiors', 'Intelligent spatial choreography for modern city living', 'Maximizing light, vertical volume, and seamless built-in storage within luxury high-rise apartments and duplexes throughout Mumbai and Mumbai.', '["Acoustic Decoupling Plans","Concealed Storage Engineering","Panoramic View Framing","Custom Fitted Wardrobes","False Ceiling Refinement"]'::jsonb, 'Transforming rigid apartment slabs into fluid, open sanctuaries with clever zoning and customized millwork.', 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?q=80&w=1400&auto=format&fit=crop', 'Building2', 3, true),
('86a10498-baea-5d17-b314-2c3f44dcfd79', 'Commercial Interiors', 'commercial-interiors', 'Ateliers, executive suites & creative studios', 'High-touch work environments that embody brand identity through refined architectural materiality and ergonomic serenity.', '["Brand Spatial Identity","Acoustic Wall Systems","Executive Boardrooms","Focus & Lounge Pods","Integrated Tech Joinery"]'::jsonb, 'Workspaces engineered to inspire deep collaboration, reduce sensory fatigue, and leave lasting impressions on visiting clients.', 'https://images.unsplash.com/photo-1497366216548-37526070297c?q=80&w=1400&auto=format&fit=crop', 'Briefcase', 4, true),
('42ade85c-1ae5-52ef-8db7-f2f4ab716143', 'Hospitality Design', 'hospitality-design', 'Boutique hotels, lounges & signature restaurants', 'Creating atmospheric, sensory-rich spaces where guests feel immediate luxury, intimacy, and a genuine sense of destination.', '["Circulation & Guest Flow Analysis","Mood & Lighting Scenes","Durable Luxury FF&E Schedules","Custom Bar & Millwork Details","Acoustic Ambience Tuning"]'::jsonb, 'We build immersive culinary and hospitality spaces that generate unforgettable memories and sustained brand reverence.', 'https://images.unsplash.com/photo-1590490360182-c33d57733427?q=80&w=1400&auto=format&fit=crop', 'Wine', 5, true),
('17249626-3f8d-5dee-8101-aa327523a35b', 'Space Planning & Architecture', 'space-planning', 'Volumetric proportion, flow & daylight optimization', 'Before choosing fabrics or finishes, we scrutinize structural layout, circulation paths, wall placements, and sunlight movement.', '["Detailed CAD Layouts","Circulation Heatmaps","Sightline & Daylight Analysis","Demolition & Masonry Plans","Furniture Proportion Diagrams"]'::jsonb, 'The mathematical backbone of every great project: getting the spatial bones and proportions fundamentally right.', 'https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?q=80&w=1400&auto=format&fit=crop', 'Layers', 6, true),
('a68539bb-0f3d-5e4c-8134-585ce0ab16ab', 'Furniture & Styling', 'furniture-styling', 'Bespoke joinery, collectible design & art curation', 'Sourcing collectible furniture, designing custom dining tables and sofas, and curating original artworks and objects that give a home its soul.', '["Custom Furniture Engineering","Art & Sculpture Acquisition","Textile & Drapery Selection","Hand-loomed Rug Design","Final White-Glove Styling"]'::jsonb, 'The emotional layer: tactile bouclés, solid walnut tables, artisanal ceramics, and books gathered with intention.', 'https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?q=80&w=1400&auto=format&fit=crop', 'Armchair', 7, true),
('eb66d686-37eb-5df0-9b34-d7b2b4c7d136', 'Turnkey Interior Design', 'turnkey-interior-design', 'Single-source accountability from concept to key handover', 'Full-spectrum design and execution stewardship. We manage contractors, schedule deliveries, conduct quality inspections, and hand over a finished residence.', '["Single Point of Contact","Weekly Progress Milestones","Budget Governance & Auditing","Trade Contractor Management","Move-in Ready Handover"]'::jsonb, 'Peace of mind. You review designs and make key decisions; our studio handles all fabrication, logistics, and site execution.', 'https://images.unsplash.com/photo-1600585154526-990dced4db0d?q=80&w=1400&auto=format&fit=crop', 'KeyRound', 8, true)
insert into process_steps (id, step_number, step_code, title, subtitle, description, deliverables, image_url, display_order) values
('e4e0ffb7-20ac-5e38-9db4-4a424972f06e', 1, '01', 'Discover', 'Immersion & Spatial Audit', 'We begin with deep architectural observation. We study the site light path, spatial orientation, structural lines, and your family daily rituals before a single sketch is drawn.', '["Site & daylight analysis","Lifestyle & ritual briefing","Budget & timeline alignment","Spatial feasibility report"]'::jsonb, 'https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?q=85&w=1600&auto=format&fit=crop', 1),
('aaca41da-f588-56f8-b13b-fb1a7c7cc710', 2, '02', 'Concept', 'Atmospheric Direction & Spatial Planning', 'We formulate the core architectural thesis. Mood studies, material tactility boards, and volumetric zoning proposals establish the emotional and physical rhythm of the space.', '["Concept narrative & mood boards","Volumetric space planning","Preliminary material palette","Initial spatial sketches"]'::jsonb, 'https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?q=85&w=1600&auto=format&fit=crop', 2),
('ed69240a-2bc8-5b53-8a27-41a1a64360ae', 3, '03', 'Design', '3D Architectural Visualization & Detailing', 'Plans evolve into high-fidelity 3D renderings and comprehensive architectural sets. Every junction, millwork detail, lighting beam angle, and ceiling transition is rigorously mapped.', '["Photorealistic 3D visualization","Detailed CAD floor plans & elevations","Lighting and electrical layout","Custom millwork design"]'::jsonb, 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?q=85&w=1600&auto=format&fit=crop', 3),
('88016015-20ed-5467-9f8b-9138b9b2e936', 4, '04', 'Detail', 'Material Sourcing & Specification', 'We physically hand-select stones, timber slabs, natural plasters, woven textiles, and architectural hardware alongside master artisans and quarry specialists.', '["Physical material swatches & boards","Hardware & sanitary schedules","Artisan joinery specifications","Contractor bid packages"]'::jsonb, 'https://images.unsplash.com/photo-1600565193348-f74bd3c7ccdf?q=85&w=1600&auto=format&fit=crop', 4),
('14067e84-bc32-53d0-bfbd-86969d879db4', 5, '05', 'Build', 'Rigorous Site Execution & Project Management', 'Our dedicated team maintains weekly on-site quality control. We coordinate specialized trades, verify millwork fabrication, and resolve site nuances with uncompromising precision.', '["Weekly site supervision & audits","Quality control milestones","Vendor coordination & schedule tracking","Structural coordination"]'::jsonb, 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?q=85&w=1600&auto=format&fit=crop', 5),
('d549c39b-3090-54f8-91f5-320f337fc8b9', 6, '06', 'Reveal', 'Curation, Art Styling & Turnkey Handover', 'The final layer transforms the architecture into a living home. We curate bespoke art, hand-loomed rugs, sculptural lighting, books, and botanicals before presenting the finished residence.', '["Art & object curation","White-glove deep cleaning & staging","Comprehensive maintenance manual","Defect liability walkthrough"]'::jsonb, 'https://images.unsplash.com/photo-1600585154526-990dced4db0d?q=85&w=1600&auto=format&fit=crop', 6)
insert into testimonials (id, client_name, client_role, project_title, testimonial, image_url, published, display_order) values
('00effd19-d739-53e4-a584-49ec724b82f7', 'Vikram & Ananya Kulkarni', 'Homeowners', 'The Courtyard Residence', 'Working with Manvvi was the single best decision of our home build. They created a sanctuary that feels both architecturally monumental and deeply comfortable for our family every morning.', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?q=80&w=400&auto=format&fit=crop', true, 1),
('1c34af96-4ca8-5745-9885-e6d3f1b0b6f9', 'Dr. Rajiv Deshmukh', 'Founder, Deshmukh Healthcare', 'Mumbai Hills Residence', 'Manvvi Design Studio possesses an uncanny restraint. Where others would have added gaudy moldings, they sculpted daylight, travertine, and cedar. It is a home that calms the pulse.', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?q=80&w=400&auto=format&fit=crop', true, 2),
('384060ca-d33b-55d3-b0a5-1a7908f36d45', 'Pooja Singhania', 'Managing Partner, Singhania Capital', 'The Ivory Apartment', 'Their turnkey execution is flawless. From our first moodboard presentation in Mumbai to receiving the keys with fully styled furniture and art, the process was seamless and on schedule.', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?q=80&w=400&auto=format&fit=crop', true, 3)
insert into gallery (id, title, image_url, category, caption, display_order, published) values
('57640d4a-76ad-5d91-8a6b-363743f1be3a', 'Honed Roman Travertine Junction', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?q=80&w=1200&auto=format&fit=crop', 'Detail', 'Mitred stone edges meeting flush European oak millwork.', 1, true),
('45f82abc-5fb7-56a5-844d-62f405382cdc', 'Diffuse Morning Light', 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?q=80&w=1200&auto=format&fit=crop', 'Light', 'Soft sunlight tracing lime plaster textures in a Bandra West residence.', 2, true),
('21d34928-df65-5221-92dc-44dbf1f39557', 'Monolithic Dining Table in Solid Oak', 'https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?q=80&w=1200&auto=format&fit=crop', 'Object', 'Custom 12-seater solid smoked oak dining table crafted in our workshop.', 3, true),
('2af3f6bc-12cc-576c-a507-70cfb2e6fbd4', 'Basalt Courtyard Water Feature', 'https://images.unsplash.com/photo-1600565193348-f74bd3c7ccdf?q=80&w=1200&auto=format&fit=crop', 'Courtyard', 'Quiet water reflection pool framed by local Maharashtra basalt.', 4, true),
('b97ef8ed-3e7b-5422-82c4-31862e40690d', 'Curved Gallery Wall', 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?q=80&w=1200&auto=format&fit=crop', 'Architecture', 'Gentle architectural radius guiding natural air circulation.', 5, true),
('9ba53b3b-bf72-56b9-bbc0-5cfba56126e6', 'Bespoke Brass Cabinetry Pulls', 'https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?q=80&w=1200&auto=format&fit=crop', 'Material', 'Solid milled champagne brass handles with subtle knurling.', 6, true)
